content:
:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  line-height: 1.5;
  color: #213547;
  background-color: #f8fafc;
}

body {
  margin: 0;
  display: flex;
  place-content: center;
  min-width: 320px;
  min-height: 100vh;
}

#root {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 2rem;
  box-sizing: border-box;
}

.app-container {
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 2rem;
  width: 100%;
  box-sizing: border-box;
}

.header {
  margin-bottom: 1.5rem;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 1rem;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1e293b;
  margin: 0;
}

.search-container {
  margin-bottom: 1.5rem;
}

.search-input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  box-sizing: border-box;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.table-container {
  overflow-x: auto;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.th {
  background-color: #f1f5f9;
  color: #475569;
  font-weight: 600;
  padding: 0.875rem 1rem;
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s;
  white-space: nowrap;
}

.th:hover {
  background-color: #e2e8f0;
}

.td {
  padding: 0.875rem 1rem;
  border-top: 1px solid #e2e8f0;
  color: #334155;
}

.employee-table tbody tr:hover {
  background-color: #f8fafc;
}

.sort-indicator {
  margin-left: 0.5rem;
  font-size: 0.8rem;
  color: #64748b;
}

@media (max-width: 640px) {
  #root {
    padding: 1rem;
  }

  .app-container {
    padding: 1rem;
  }

  .th, .td {
    padding: 0.75rem 0.5rem;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export interface SortConfig {
  key: keyof Employee;
  direction: 'asc' | 'desc';
}

import { FC } from 'react';

interface SearchBarProps {
  value: string;
  onChange: (value: string) => void;
}

export const SearchBar: FC<SearchBarProps> = ({ value = '', onChange }) => {
  return (
    <div className="search-container">
      <input
        type="text"
        className="search-input"
        placeholder="名前で絞り込み..."
        value={value}
        onChange={(e) => onChange?.(e.target.value)}
      />
    </div>
  );
};

export default SearchBar;

import { FC } from 'react';
import { Employee, SortConfig } from '../types';

interface EmployeeTableProps {
  employees: Employee[];
  sortConfig: SortConfig;
  onSort: (key: keyof Employee) => void;
}

export const EmployeeTable: FC<EmployeeTableProps> = ({
  employees = [],
  sortConfig,
  onSort,
}) => {
  const renderSortIndicator = (key: keyof Employee) => {
    if (sortConfig.key !== key) return null;
    return (
      <span className="sort-indicator">
        {sortConfig.direction === 'asc' ? '▲' : '▼'}
      </span>
    );
  };

  return (
    <div className="table-container">
      <table className="employee-table">
        <thead>
          <tr>
            <th className="th" onClick={() => onSort?.('id')}>
              ID {renderSortIndicator('id')}
            </th>
            <th className="th" onClick={() => onSort?.('name')}>
              名前 {renderSortIndicator('name')}
            </th>
            <th className="th" onClick={() => onSort?.('department')}>
              部署 {renderSortIndicator('department')}
            </th>
            <th className="th" onClick={() => onSort?.('age')}>
              年齢 {renderSortIndicator('age')}
            </th>
          </tr>
        </thead>
        <tbody>
          {employees.length === 0 ? (
            <tr>
              <td className="td" colSpan={4} style={{ textAlign: 'center', color: '#64748b' }}>
                該当する社員がいません
              </td>
            </tr>
          ) : (
            employees.map((emp) => (
              <tr key={emp.id}>
                <td className="td">{emp.id}</td>
                <td className="td">{emp.name}</td>
                <td className="td">{emp.department}</td>
                <td className="td">{emp.age}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default EmployeeTable;

import { useState, useMemo } from 'react';
import './index.css';
import { Employee, SortConfig } from './types';
import SearchBar from './components/SearchBar';
import EmployeeTable from './components/EmployeeTable';

const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健', department: '開発部', age: 28 },
  { id: 2, name: '鈴木 美咲', department: '人事部', age: 34 },
  { id: 3, name: '高橋 航', department: '営業部', age: 41 },
  { id: 4, name: '田中 葵', department: '開発部', age: 25 },
  { id: 5, name: '伊藤 蓮', department: 'マーケティング部', age: 30 },
  { id: 6, name: '渡辺 陽菜', department: '経理部', age: 38 },
  { id: 7, name: '山本 拓海', department: '営業部', age: 29 },
  { id: 8, name: '中村 結衣', department: '人事部', age: 27 },
  { id: 9, name: '小林 翔', department: '開発部', age: 45 },
  { id: 10, name: '加藤 莉子', department: '経理部', age: 32 },
];

export default function App() {
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: 'id',
    direction: 'asc',
  });

  const handleSort = (key: keyof Employee) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredAndSortedEmployees = useMemo(() => {
    let result = initialEmployees.filter((emp) =>
      emp.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    result.sort((a, b) => {
      const aVal = a[sortConfig.key];
      const bVal = b[sortConfig.key];

      if (aVal < bVal) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (aVal > bVal) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });

    return result;
  }, [searchQuery, sortConfig]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員一覧</h1>
      </header>
      <SearchBar value={searchQuery} onChange={setSearchQuery} />
      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortConfig={sortConfig}
        onSort={handleSort}
      />
    </div>
  );
}
